package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.special.Erf;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.MathMissingException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NormalDistributionImpl#cumulativeProbability
 */
public class NormalDistributionImpl_cumulativeProbability_TriageGen4Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testCumulativeProbability_StandardNormal_AtMean() throws Exception {
        // Standard Normal Distribution: mean = 0, sd = 1
        NormalDistributionImpl dist = new NormalDistributionImpl(0.0, 1.0);
        // For a standard normal distribution, P(X <= 0) should be 0.5
        double result = dist.cumulativeProbability(0.0);
        Assert.assertEquals(0.5, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_StandardNormal_PositiveValue() throws Exception {
        NormalDistributionImpl dist = new NormalDistributionImpl(0.0, 1.0);
        // P(X <= 1) for standard normal is approx 0.841344746
        double result = dist.cumulativeProbability(1.0);
        Assert.assertEquals(0.8413447460685429, result, 1e-9);
    }

    @Test
    public void testCumulativeProbability_StandardNormal_NegativeValue() throws Exception {
        NormalDistributionImpl dist = new NormalDistributionImpl(0.0, 1.0);
        // P(X <= -1) should be 1 - P(X <= 1)
        double result = dist.cumulativeProbability(-1.0);
        Assert.assertEquals(0.158655253931457, result, 1e-9);
    }

    @Test
    public void testCumulativeProbability_CustomMeanAndSD() throws Exception {
        // Mean = 10, SD = 2
        NormalDistributionImpl dist = new NormalDistributionImpl(10.0, 2.0);
        // P(X <= 10) should be 0.5
        Assert.assertEquals(0.5, dist.cumulativeProbability(10.0), DELTA);
        // P(X <= 12) is equivalent to P(Z <= (12-10)/2) = P(Z <= 1)
        Assert.assertEquals(0.8413447460685429, dist.cumulativeProbability(12.0), 1e-9);
    }

    @Test
    public void testCumulativeProbability_ExtremeValues() throws Exception {
        NormalDistributionImpl dist = new NormalDistributionImpl(0.0, 1.0);

        // Very large positive value -> probability approaches 1.0
        Assert.assertEquals(1.0, dist.cumulativeProbability(100.0), DELTA);

        // Very large negative value -> probability approaches 0.0
        Assert.assertEquals(0.0, dist.cumulativeProbability(-100.0), DELTA);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testCumulativeProbability_InvalidStandardDeviation_Zero() {
        // Standard deviation must be positive
        NormalDistributionImpl dist = new NormalDistributionImpl(0.0, 0.0);
        try {
            dist.cumulativeProbability(1.0);
        } catch (MathIllegalArgumentException e) {
            // Re-throw to satisfy expected
            throw e;
        }
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testCumulativeProbability_InvalidStandardDeviation_Negative() {
        NormalDistributionImpl dist = new NormalDistributionImpl(0.0, -1.0);
        dist.cumulativeProbability(1.0);
    }

    @Test
    public void testCumulativeProbability_AfterSetters() throws Exception {
        NormalDistributionImpl dist = new NormalDistributionImpl();
        dist.setMean(5.0);
        dist.setStandardDeviation(2.5);

        // P(X <= 5) = 0.5
        Assert.assertEquals(0.5, dist.cumulativeProbability(5.0), DELTA);

        // P(X <= 7.5) -> Z = (7.5 - 5) / 2.5 = 1.0
        Assert.assertEquals(0.8413447460685429, dist.cumulativeProbability(7.5), 1e-9);
    }
}
